//go:build amd64

package floats

// The AVX2+FMA kernel of AllPass3 (allpass.go), generated by go-asmgen
// (allpass_amd64_gen.go) into allpass_amd64.s: two rows per ymm register, one row in an
// xmm register for an odd tail, for a CPU with the AVX2+FMA of the other kernels
// (hasAVX2FMA, kernels_amd64.go); the portable math.FMA loop otherwise, with the same
// bits. The caller guarantees n >= 1 and the lengths of every operand. Every operand is
// passed as a pointer to its first element. No kernel keeps a pointer: go:noescape.
//
//go:noescape
func allPass3AVX2(n int, out, in, phi, q0, q1, q2 *complex128, c0, c1, c2 *float64, old0, new0, old1, new1, old2, new2 *complex128)

func allPass3(n int, out, in []complex128, t *AllPassRows, old, cur *[3][]complex128) {
	if hasAVX2FMA {
		allPass3AVX2(n, &out[0], &in[0], &t.Phi[0], &t.Q0[0], &t.Q1[0], &t.Q2[0], &t.C0[0], &t.C1[0], &t.C2[0],
			&old[0][0], &cur[0][0], &old[1][0], &cur[1][0], &old[2][0], &cur[2][0])
		return
	}
	allPass3Ref(n, out, in, t, old, cur)
}
